(function() {
"use strict";
function toggleScrolled() {
const selectBody = document.body;
const selectHeader = document.querySelector('#header');
if (!selectHeader || (!selectHeader.classList.contains('scroll-up-sticky') && !selectHeader.classList.contains('sticky-top') && !selectHeader.classList.contains('fixed-top'))) return;
window.scrollY > 100 ? selectBody.classList.add('scrolled') : selectBody.classList.remove('scrolled');
}document.addEventListener('scroll', toggleScrolled, { passive: true });
window.addEventListener('load', toggleScrolled);
const mobileNavToggleBtn = document.querySelector('.mobile-nav-toggle');function mobileNavToogle() {
document.body.classList.toggle('mobile-nav-active');
if (mobileNavToggleBtn) {
mobileNavToggleBtn.classList.toggle('bi-list');
mobileNavToggleBtn.classList.toggle('bi-x');
}
}if (mobileNavToggleBtn) {
mobileNavToggleBtn.addEventListener('click', mobileNavToogle);
}
document.querySelectorAll('#navmenu a').forEach(navmenu => {
navmenu.addEventListener('click', function(e) {
const href = this.getAttribute('href');
const hasSubmenu = this.nextElementSibling && this.nextElementSibling.tagName === 'UL';
const isMobileNavActive = document.querySelector('.mobile-nav-active');
const isMobileScreen = window.innerWidth < 1200;if (hasSubmenu && (isMobileNavActive || isMobileScreen || href === '#' || href === 'javascript:void(0);')) {
e.preventDefault();
e.stopPropagation();
this.classList.toggle('active');
if (this.parentNode) {
this.parentNode.classList.toggle('active');
}
if (this.nextElementSibling) {
this.nextElementSibling.classList.toggle('dropdown-active');
}
return;
}if (href === '#' || href === 'javascript:void(0);') {
e.preventDefault();
return;
}if (document.querySelector('.mobile-nav-active')) {
mobileNavToogle();
}
});
});
const preloader = document.querySelector('#preloader');
if (preloader) {
window.addEventListener('load', () => {
preloader.remove();
});
}
const scrollTop = document.querySelector('.scroll-top');
const waFloat = document.querySelector('.whatsapp-float');function toggleScrollTop() {
if (scrollTop) {
if (window.scrollY > 100) {
scrollTop.classList.add('active');
if (waFloat) waFloat.classList.add('scroll-active');
} else {
scrollTop.classList.remove('active');
if (waFloat) waFloat.classList.remove('scroll-active');
}
}
}if (scrollTop) {
scrollTop.addEventListener('click', (e) => {
e.preventDefault();
window.scrollTo({ top: 0, behavior: 'smooth' });
});
}window.addEventListener('load', toggleScrollTop);
document.addEventListener('scroll', toggleScrollTop, { passive: true });
function aosInit() {
if (typeof AOS !== 'undefined') {
AOS.init({
duration: 600,
easing: 'ease-in-out',
once: true,
mirror: false
});
}
}
window.addEventListener('load', aosInit);
function initNativeCounter() {
const counters = document.querySelectorAll('.purecounter');
if (!counters.length) return;const observer = new IntersectionObserver((entries) => {
entries.forEach(entry => {
if (entry.isIntersecting) {
const el = entry.target;
const start = parseInt(el.getAttribute('data-purecounter-start') || '0', 10);
const end = parseInt(el.getAttribute('data-purecounter-end') || el.innerText.replace(/[^0-9]/g, '') || '0', 10);
const duration = (parseFloat(el.getAttribute('data-purecounter-duration') || '1')) * 1000;
let startTime = null;
function animate(currentTime) {
if (!startTime) startTime = currentTime;
const progress = Math.min((currentTime - startTime) / duration, 1);
const val = Math.floor(progress * (end - start) + start);
el.innerText = val.toLocaleString();
if (progress < 1) {
requestAnimationFrame(animate);
} else {
el.innerText = end.toLocaleString();
}
}
requestAnimationFrame(animate);
observer.unobserve(el);
}
});
}, { threshold: 0.1 });counters.forEach(c => observer.observe(c));
}
window.addEventListener('load', initNativeCounter);
function initNativeFilters() {
document.querySelectorAll('.isotope-layout').forEach(layoutItem => {
const filters = layoutItem.querySelectorAll('.isotope-filters li');
const items = layoutItem.querySelectorAll('.isotope-item');
if (!filters.length || !items.length) return;filters.forEach(filterBtn => {
filterBtn.addEventListener('click', function() {
filters.forEach(f => f.classList.remove('filter-active'));
this.classList.add('filter-active');const filterValue = this.getAttribute('data-filter');
items.forEach(item => {
if (filterValue === '*' || item.classList.contains(filterValue.replace('.', ''))) {
item.style.display = '';
} else {
item.style.display = 'none';
}
});
if (typeof AOS !== 'undefined') AOS.refresh();
});
});
});
}
window.addEventListener('load', initNativeFilters);
function initSwiper() {
if (typeof Swiper === 'undefined') return;
document.querySelectorAll(".init-swiper").forEach(function(swiperElement) {
const configEl = swiperElement.querySelector(".swiper-config");
if (!configEl) return;
let config = JSON.parse(configEl.innerHTML.trim());
new Swiper(swiperElement, config);
});
}
window.addEventListener("load", initSwiper);
function initLightbox() {
if (typeof GLightbox !== 'undefined' && document.querySelector('.glightbox')) {
GLightbox({ selector: '.glightbox' });
}
}
window.addEventListener("load", initLightbox);
function initDynamicPagination() {
const paginationContainers = document.querySelectorAll('[data-pagination-group]');
paginationContainers.forEach(groupContainer => {
const groupName = groupContainer.getAttribute('data-pagination-group');
const pages = groupContainer.querySelectorAll('.pagination-page');
const paginationNav = document.querySelector(`[data-pagination-nav="${groupName}"]`);
if (!pages.length || !paginationNav) return;
let totalPages = pages.length;
let currentPage = 1;
function showPage(pageNum) {
if (pageNum < 1) pageNum = 1;
if (pageNum > totalPages) pageNum = totalPages;
currentPage = pageNum;
pages.forEach(p => {
const pVal = parseInt(p.getAttribute('data-page'), 10);
if (pVal === currentPage) {
p.style.display = 'block';
p.classList.add('active-page');
} else {
p.style.display = 'none';
p.classList.remove('active-page');
}
});
const numBtns = paginationNav.querySelectorAll('.page-btn[data-page]');
numBtns.forEach(btn => {
const pVal = parseInt(btn.getAttribute('data-page'), 10);
const parentLi = btn.closest('li');
if (pVal === currentPage) {
btn.classList.add('active');
if (parentLi) parentLi.classList.add('active');
} else {
btn.classList.remove('active');
if (parentLi) parentLi.classList.remove('active');
}
});
const prevBtn = paginationNav.querySelector('.page-prev');
const nextBtn = paginationNav.querySelector('.page-next');
if (prevBtn) {
currentPage === 1 ? prevBtn.classList.add('disabled') : prevBtn.classList.remove('disabled');
}
if (nextBtn) {
currentPage === totalPages ? nextBtn.classList.add('disabled') : nextBtn.classList.remove('disabled');
}
if (typeof AOS !== 'undefined') AOS.refresh();
}
paginationNav.querySelectorAll('.page-btn[data-page]').forEach(btn => {
btn.addEventListener('click', function(e) {
e.preventDefault();
showPage(parseInt(this.getAttribute('data-page'), 10));
groupContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });
});
});
const prevBtn = paginationNav.querySelector('.page-prev');
if (prevBtn) {
prevBtn.addEventListener('click', function(e) {
e.preventDefault();
if (currentPage > 1) {
showPage(currentPage - 1);
groupContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });
}
});
}
const nextBtn = paginationNav.querySelector('.page-next');
if (nextBtn) {
nextBtn.addEventListener('click', function(e) {
e.preventDefault();
if (currentPage < totalPages) {
showPage(currentPage + 1);
groupContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });
}
});
}
showPage(1);
});
}window.addEventListener('load', initDynamicPagination);
document.addEventListener('DOMContentLoaded', initDynamicPagination);})();